        super(message);
        this.status = status;
        this.code = code;
        this.details = details;
    }

    public String code() {
        return code;
    }

    public HttpStatus status() {
        return status;
    }

    /** 结构化错误明细；无明细返回 null。 */
    public Map<String, Object> details() {
