    void corridorOverlapRules() {
        long now = System.currentTimeMillis();
        corridorService.createCorridor(corridorReq("c1", 1, now, now + 3_600_000, 100, 200));

        // 同优先级时空重叠 → 409 并给出冲突走廊标识
